// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint48 t1, uint48 t2, address actor) public {
        vm.assume(t1 >= 2);
        vm.assume(actor != address(0) && actor != address(c));
        bound(t2, 1, type(uint48).max);

        // first call at timestamp t1: admissible, must succeed and record pastBlockTime = t1
        vm.warp(t1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        assertEq(c.pastBlockTime(), uint256(t1));

        // second call at timestamp t2
        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // GENERAL RULE: a fallback call can only succeed at a timestamp STRICTLY
        // greater than the last recorded one. If it succeeded at t2, then t2 > t1.
        assertTrue(!(ok2 && uint256(t2) <= uint256(t1)), "second call succeeded at non-increasing timestamp");
    }
}
